insert into public.projects (slug, title, description, image_media_id, github_url, youtube_video_id, sort_order) values
('driving-simulator', 'Driving Simulator', 'Developed a VR-based driving simulator for training purposes using Unity. The simulator includes realistic vehicle physics, traffic environments, and user interaction through VR controllers for immersive driving practice.', (select id from public.media where slug = 'asset-driving'), 'https://github.com/aditya29mishra/car-simulator', null, 0),
('mr-btech-electronics-training-modules', 'MR BTECH Electronics Training Modules', 'Developed mixed reality (MR) training modules for B.Tech electronics students, enabling interactive learning of electronic components, circuits, and lab procedures through immersive visualization.', (select id from public.media where slug = 'asset-mrElectronics'), null, 'BGQeamOWpto', 1),
('vr-lathe-machine-training', 'VR Lathe Machine Training', 'Developed an immersive VR lathe machine simulator to train users on machining operations including cutting, shaping, and finishing processes with realistic machine controls and safety procedures.', (select id from public.media where slug = 'asset-lathe'), 'https://github.com/aditya29mishra/lath-main', 'dvt7lDIhXM0', 2),
('crane-simulator', 'Crane Simulator', 'Designed a virtual reality crane operation simulator allowing users to learn safe crane handling, load lifting, and positioning techniques within a simulated industrial environment.', (select id from public.media where slug = 'asset-crane'), null, 'dkbr6-Xl2bI', 3),
('advanced-vr-welding-simulator', 'Advanced VR Welding Simulator', 'A highly detailed VR welding training simulator featuring realistic welding physics, multiple welding techniques, material interaction, and safety training for industrial applications.', (select id from public.media where slug = 'asset-weldingAdvanced'), null, 'JqyANAGsmrM', 4),
('fire-safety-training', 'Fire Safety Training', 'A VR module that simulates emergency fire scenarios, teaching users how to identify hazards, use fire extinguishers, and safely evacuate through guided training steps.', (select id from public.media where slug = 'asset-fire'), null, 'MjWuah5y4wQ', 5),
('screwing-process-training', 'Screwing Process Training', 'An interactive training experience where users learn and perform step-by-step screwing operations using virtual tools in a controlled, immersive environment.', (select id from public.media where slug = 'asset-screw'), null, null, 6),
('terminal-fixing', 'Terminal Fixing', 'This module trains users on correctly placing and securing terminal components in assemblies processes, ensuring precision and safety during the process.', (select id from public.media where slug = 'asset-terminal'), null, null, 7),
('holder-fixing', 'Holder Fixing', 'A VR simulation focused on fixing holders into Workpiece, guiding users through part handling, alignment, and secure fitting procedures.', (select id from public.media where slug = 'asset-safe'), null, null, 8),
('uno-minda-die-casting-training', 'UNO Minda Die Casting Training', 'A VR industrial training module that teaches operators the die casting process including material handling, mold operation, and safety procedures inside a simulated manufacturing environment.', (select id from public.media where slug = 'asset-dieCasting'), null, 'uUNEoHJALEo', 9),
('uno-minda-leakage-testing', 'UNO Minda Leakage Testing', 'A VR training module designed to teach operators how to perform leakage testing procedures on casting components, identify defects, and safely operate leakage testing machines.', (select id from public.media where slug = 'asset-leakageTesting'), null, '8dG_NnXF7xQ', 10),
('uno-minda-painting-process', 'UNO Minda Painting Process', 'Simulates the industrial painting workflow for casting components, training operators on proper handling, coating procedures, and quality inspection inside a virtual environment.', (select id from public.media where slug = 'asset-painting'), null, 'xaynvTT2mmQ', 11),
('uno-minda-pdi-inspection', 'UNO Minda PDI Inspection', 'A VR training module for Pre-Delivery Inspection (PDI) that helps users learn inspection procedures, defect detection, and quality verification for casting components.', (select id from public.media where slug = 'asset-pdi'), null, 'Ip5nZ9iEM44', 12),
('uno-minda-plug-in-process', 'UNO Minda Plug-In Process', 'An immersive VR simulation where users learn the plug-in assembly process including component placement, alignment, and secure fitting procedures in an industrial workflow.', (select id from public.media where slug = 'asset-plugin'), null, null, 13),
('uno-minda-vmc-operation', 'UNO Minda VMC Operation', 'A virtual reality training simulator that teaches operators how to work with Vertical Machining Centers (VMC), including machine setup, machining workflow, and safety practices.', (select id from public.media where slug = 'asset-vmc'), null, null, 14),
('3d-chess-game', '3D Chess Game', 'Multiplayer 3D chess game using Unity and Blender. Implemented server-client architecture in .NET for online multiplayer and used OOP principles for maintainable code.', (select id from public.media where slug = 'asset-chess'), 'https://github.com/aditya29mishra/3d-chess-game', null, 15),
('tagore-hostel-fps-game', 'Tagore Hostel (FPS Game)', 'Developed a first-person shooting game in Unreal Engine, creating a detailed environment and interactive shooting mechanics.', (select id from public.media where slug = 'asset-tagoreHostel'), null, null, 16),
('plus-one-dimension', '+1 Dimension', 'Built a virtual reality property exploration system with customizable room layouts and AR visualization using marker-based technology.', (select id from public.media where slug = 'asset-plusOneDimension'), null, null, 17),
('spotify-clone', 'Spotify Clone', 'AM Music App is a Kotlin-based music streaming platform using Jetpack Compose, Spotify API integration, and Firebase.', (select id from public.media where slug = 'asset-amMusic'), null, null, 18),
('iit-jodhpur-navigational-mapping', 'IIT Jodhpur Navigational Mapping', 'Developed an AR-based campus navigation system for IIT Jodhpur using Unity, ARCore, and Flutter.', (select id from public.media where slug = 'asset-ihub'), null, null, 19),
('quiz-game', 'Quiz Game', 'Interactive 3D quiz game in Unity using C#, Blender, and Firebase.', (select id from public.media where slug = 'asset-quizGame'), 'https://github.com/aditya29mishra/quiz-Game', null, 20),
('flappy-bird', 'Flappy Bird', '2D mobile game in Unity with custom physics and Firebase leaderboard.', (select id from public.media where slug = 'asset-flappyBird'), 'https://github.com/aditya29mishra/AM-Birdy', null, 21);
