('elektro-labs-junior-unity-developer', 'ELEKTRO LABs', 'work', 'Junior Unity Developer', 'Unity3D, C#, AR/VR/MR', 'I create VR training modules for DOJO, including Fire Safety Training, Screwing Process Training, Terminal & Holder Fixing, and PDI Training. My responsibilities include programming, designing training flows, and managing client interactions and deployments.', 'Feb 2025 - Present', 0),
('algovation-game-developer-intern', 'Algovation.in', 'work', 'Game Devloper Intern', 'Unity3d, C# ', 'Developing engaging mobile-based games using Unity3D. Focused on optimizing gameplay mechanics, implementing interactive features, and delivering high-quality gaming experiences tailored for mobile platforms.', 'Dec 2024 -  JAN 2025', 1),
('iit-jodhpur-tih-ihub-drishti-intern', 'IIT Jodhpur', 'work', 'Intern at TIH iHUB Drishti', 'Unity, C#, ARCore, Android SDKs', 'Developed high-performance AR/VR software solutions, optimized real-time performance, and collaborated with interdisciplinary teams for interactive XR experiences.', 'July 2024 - Sep 2024', 2),
('aditya-mishra-hackathon-achievements', 'Aditya Mishra', 'work', 'Hackathon Achievements', 'Problem-Solving, AR/VR, Team Collaboration', 'Winner of Kumbh Mela Hackathon (IIITA, 2024), InnoHacks''23 Hackathon, and Innotech''22 KIET annual technical fest.', '2022 - 2024', 3),
('kiet-group-of-institution-btech-computer-science', 'KIET Gruop of institution', 'education', 'B.Tech in Computer Science', null, 'Pursuing final year with a strong focus on Machine Learning, AI, and AR/VR projects. Actively involved in hands-on projects and internships to enhance technical and practical knowledge.', 'Aug 2021 - May 2025', 4);
